xhtml:div.script:

const asset = document.getElementById("asset");
const cdn = document.getElementById("cdn");
const version = document.getElementById("version");
const output = document.getElementById("output");
const status = document.getElementById("status");

function generate() {
  const file = asset.value;
  const ref = version.value.trim() || "main";
  const repo = "theofficalnothing-arch/securly";
  let url = "";

  if (cdn.value === "jsdelivr") {
    url = "https://cdn.jsdelivr.net/gh/" + repo + "@" + ref + "/" + file;
  } else if (cdn.value === "esm") {
    url = "https://esm.sh/gh/" + repo + "@" + ref + "/" + file;
  } else if (cdn.value === "raw") {
    url = "https://raw.githubusercontent.com/" + repo + "/" + ref + "/" + file;
  } else if (cdn.value === "unpkg") {
    url = "https://unpkg.com/securly-assets@1.0.1/" + file;
  }

  output.textContent = url;
  status.textContent = "Link generated.";
  return url;
}

asset.addEventListener("change", generate);
cdn.addEventListener("change", generate);
version.addEventListener("input", generate);

document.getElementById("copy").addEventListener("click", async () => {
  try {
    await navigator.clipboard.writeText(generate());
    status.textContent = "Copied!";
  } catch (e) {
    status.textContent = "Copy unavailable. Select the URL and copy it manually.";
  }
});

document.getElementById("open").addEventListener("click", () => {
  window.open(generate(), "_blank", "noopener,noreferrer");
});

generate();
